import tables from "@/data/tables";
import queries from "@/data/queries";
import { ref } from "vue";
export default {
  name: "NavbarMenu",
  data: {
    url: 'http://localhost:8081/login',
    name: "blogs"
  },
  methods: {
    goto: function () {
      window.location = this.$data.url;
    },

    handle(name) {
      this.$router.push({
        name: name
      });
    },

    secondHandle(name, path) {
      this.$router.push({
        name: name,
        params: {
          link: path,
          name: name
        }
      });
    }

  },

  setup() {
    const allTables = ref(tables);
    const allQueries = ref(queries);
    return {
      allTables,
      allQueries
    };
  }

};
